def is_valid(isbn):
    if not isinstance(isbn, str):
        return False

    # Remove hyphens only; other characters (including spaces) are invalid
    chars = [c for c in isbn if c != '-']

    # Must be exactly 10 characters after removing hyphens
    if len(chars) != 10:
        return False

    total = 0
    for i, ch in enumerate(chars):
        weight = 10 - i
        # Last character can be 'X' which represents 10
        if i == 9 and ch == 'X':
            value = 10
        else:
            if not ch.isdigit():
                return False
            value = int(ch)
        total += value * weight

    return total % 11 == 0
